import sys

def find_minimum_i(n, k, A):
    current_sum = 0
    for i in range(n):
        current_sum += A[i]
        if current_sum >= k:
            return 0

    i = 1
    while True:
        new_A = [0] * (n + 1)
        new_A[0] = A[0]
        for j in range(1, n + 1):
            new_A[j] = new_A[j - 1] + A[j - 1]

        for value in new_A:
            if value >= k:
                return i

        A = new_A
        i += 1

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])
    A = list(map(int, data[2:2+n]))

    result = find_minimum_i(n, k, A)
    print(result)

if __name__ == "__main__":
    main()
